'use strict';
const $=(q)=>document.querySelector(q);
const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,sz=20)=>{const paths={book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1v15"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v3"/>',leaf:'<path d="M20 3c-9 0-17 2-17 9a7 7 0 0 0 7 7c7 0 10-7 10-16ZM3 21 15 9"/>',grid:'<path d="M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h6v6h-6z"/>',library:'<path d="m3 9 9-6 9 6H3Zm2 3v7m7-7v7m7-7v7M2 22h20"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',check:'<path d="m5 12 4 4L20 5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',link:'<path d="M14 3h7v7m0-7L11 13M10 5H4v15h15v-6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};return `<svg width="${sz}" height="${sz}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.book}</svg>`;};
const NAV=[['reader','book','The Gita','गीता अध्ययन'],['ask','spark','Ask the Gita','मन की बात'],['mantras','sun','Mantras','मन्त्र एवं प्रार्थना'],['characters','people','Lives & lessons','चरित्र और जीवन'],['practice','leaf','Daily practice','नित्य अभ्यास'],['epic','grid','The Mahabharata','महाभारत'],['scriptures','library','Scripture library','शास्त्र परिचय']];
let verses=[],byRef={},loadError=false;
const storage={get(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{return fallback}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}}};
let state={page:'reader',ref:'2.47',lang:storage.get('dharma-lang','en'),query:'',question:'',journey:null,unknown:false,epicTab:'formations',formation:'chakra',character:'arjuna',epicFilter:'All',habit:'scroll',editing:false,plan:storage.get('dharma-practice',null)};
if(!['en','hi','both'].includes(state.lang))state.lang='en';
if(state.plan&&(!['name','cue','action','verse'].every(k=>typeof state.plan[k]==='string')||!Array.isArray(state.plan.days)||state.plan.days.length!==7||!HABITS.some(h=>h.id===state.plan.habit)))state.plan=null;
function sourceUrl(ref){const[c,v]=ref.split('.');return `https://www.gitasupersite.iitk.ac.in/srimad?language=dv&field_chapter_value=${c}&field_nsutra_value=${v}&etsiva=1&htrskd=1&httyn=1`;}
const sourceLink=(url,text)=>`<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)} ${icon('link',14)}</a>`;
function go(page,ref){const hash=`#${page}${ref?'/'+ref:''}`;if(location.hash===hash){render();window.scrollTo({top:0,behavior:'smooth'})}else location.hash=hash;}
function parseRoute(){const oldPage=state.page,oldRef=state.ref,oldY=window.scrollY;const [p,r]=location.hash.slice(1).split('/');const turn=oldPage==='reader'&&p==='reader'&&byRef[r]&&r!==oldRef?capturePageTurn('.reader-workspace .verse-body'):null;state.editing=false;state.page=[...NAV.map(n=>n[0]),'sources'].includes(p)?p:'reader';if(state.page==='reader'&&r&&byRef[r])state.ref=r;if(state.page==='mantras'&&r&&MANTRAS.some(m=>m.id===r)){mantraState.selected=r;mantraState.topic='all';mantraState.query='';mantraState.kind='all';}render();if(oldPage==='reader'&&state.page==='reader'&&oldRef!==state.ref){finishPageTurn(turn,'.reader-workspace .verse-body',verses.indexOf(byRef[state.ref])-verses.indexOf(byRef[oldRef]));window.scrollTo({top:oldY,behavior:'instant'});}else window.scrollTo({top:0,behavior:'instant'});}
function header(title,sa,desc){return `<div class="page-title"><div><p class="eyebrow">${sa}</p><h1>${title}</h1>${desc?`<p class="lede">${desc}</p>`:''}</div></div>`;}
function shell(content){return `<a class="skip-link" href="#main">Skip to content</a><aside class="sidebar" id="side"><a class="brand" href="#reader"><span class="brand-mark">ध</span><span>Dharma<small>A SCRIPTURE COMPANION</small></span></a><div class="side-rule"><span>स्वाध्याय</span></div><nav aria-label="Main navigation">${NAV.map(([id,ic,name,sa])=>`<a href="#${id}" class="nav-item ${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${icon(ic)}<span>${name}<small lang="hi">${sa}</small></span>${state.page===id?'<span class="nav-dot"></span>':''}</a>`).join('')}</nav><div class="side-bottom"><p lang="sa">ज्ञानदीपेन भास्वता</p><small>By the shining lamp of knowledge</small><a href="#reader/10.11">Bhagavad Gita 10.11</a><a class="side-source ${state.page==='sources'?'selected':''}" href="#sources">${icon('shield',18)} Our sources & approach</a></div></aside><div class="main-shell"><header class="topbar mythic-frame"><div class="header-start"><button class="icon-button menu-button" id="menu-toggle" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><span class="breadcrumb">THE STUDY <span>/</span> ${NAV.find(n=>n[0]===state.page)?.[2]||'Sources & approach'}</span></div><span class="header-chakra">${chakraEmblem('top')}</span><a class="top-source" href="#sources">${icon('shield',16)} Grounded in the text</a></header><main id="main" tabindex="-1">${content}</main><footer class="mythic-frame"><span class="footer-identity">${chakraEmblem('bottom')}<span class="footer-brand">धर्म <span>Read. Reflect. Practice.</span></span></span><a href="#sources">Texts, traditions & attributions ${icon('link',13)}</a><div class="contact-mini" aria-label="Contact Gourav Dutta"><span>Contact Gourav</span><a href="https://www.instagram.com/yupitsmegd7/" target="_blank" rel="noopener noreferrer">Instagram ${icon('link',12)}</a><a href="https://www.linkedin.com/in/gourav-dutta-958892299/" target="_blank" rel="noopener noreferrer">LinkedIn ${icon('link',12)}</a></div></footer></div><div class="toast" id="toast" role="status"></div>`;}
function loading(){return `<div class="panel error-panel"><h2>${loadError?'The text could not be opened.':'Opening the Gita…'}</h2><p>${loadError?'Please try loading the local verse collection again. Your practice is still on this device.':'Preparing the complete Sanskrit, Hindi and English reader.'}</p>${loadError?'<button class="btn primary" id="retry-load">Try again</button>':''}</div>`;}
function languageButtons(){return `<div class="segmented" aria-label="Translation language">${[['en','English'],['hi','हिन्दी'],['both','Both']].map(([id,label])=>`<button data-lang="${id}" class="${state.lang===id?'selected':''}" aria-pressed="${state.lang===id}">${label}</button>`).join('')}</div>`;}
function verseText(v,compact=false){return `<div class="sanskrit ${compact?'compact':''}" lang="sa">${esc(v.sanskrit).replace(/\n{2,}/g,'\n')}</div><details class="roman"><summary>Roman transliteration</summary><p>${esc(v.roman)}</p></details><div class="translation">${state.lang!=='hi'?`<div><span class="small-label">ENGLISH MEANING</span><p>${esc(v.en)}</p><span class="attribution">Translation · Swami Sivananda</span></div>`:''}${state.lang!=='en'?`<div lang="hi"><span class="small-label">हिन्दी अर्थ</span><p>${esc(v.hi)}</p><span class="attribution">अनुवाद · ${esc(v.hindiAuthor)}</span></div>`:''}</div>`;}
function reader(){const v=byRef[state.ref],chapter=CHAPTERS.find(c=>c.n===(v?.chapter||2));const refs=REFLECTIONS[state.ref];return `<section class="reader-intro"><div><p class="eyebrow">स्वाध्याय · THE BHAGAVAD GITA</p><h1>Ancient wisdom.<br><em>For the life you live.</em></h1><p class="lede">A verse to understand. A moment to reflect.<br>A teaching to carry into your day.</p><div class="intro-meta"><span><b>18</b> adhyayas</span><i></i><span><b>701</b> verse entries <a href="#sources" aria-label="About verse numbering">ⓘ</a></span><i></i><span>संस्कृत · हिन्दी · English</span></div></div><figure class="intro-art"><img src="/assets/krishna-arjuna.webp" width="1536" height="1024" alt="Contemporary miniature-inspired artwork of Krishna teaching Arjuna on a chariot at Kurukshetra"><figcaption>THE DIALOGUE AT KURUKSHETRA</figcaption></figure></section><div class="section-heading"><h2>${icon('book',21)} Open the scripture</h2><button class="text-button" id="chapters-toggle">Browse all 18 chapters ${icon('grid',16)}</button></div><div id="chapter-index" hidden class="chapter-grid">${CHAPTERS.map(c=>`<button data-chapter="${c.n}"><span>${String(c.n).padStart(2,'0')}</span><div><strong>${c.title}</strong><small>${c.count} verses · ${c.name}</small></div></button>`).join('')}</div>${!v?loading():`<div class="reader-workspace"><article class="verse-paper"><div class="reader-controls"><label><span class="small-label">ADHYAYA · अध्याय</span><select id="chapter-select">${CHAPTERS.map(c=>`<option value="${c.n}" ${c.n===v.chapter?'selected':''}>${String(c.n).padStart(2,'0')} · ${c.title}</option>`).join('')}</select></label><label class="verse-select-label"><span class="small-label">SHLOKA · श्लोक</span><select id="verse-select">${verses.filter(x=>x.chapter===v.chapter).map(x=>`<option value="${x.ref}" ${x.ref===v.ref?'selected':''}>${x.number}</option>`).join('')}</select></label><button id="prev-top" class="icon-button" aria-label="Previous verse" ${v.ref==='1.1'?'disabled':''}>${icon('left')}</button><button id="next-top" class="icon-button" aria-label="Next verse" ${v.ref==='18.78'?'disabled':''}>${icon('right')}</button></div><div class="search-row">${icon('search',17)}<label class="sr-only" for="verse-search">Search all verses or enter a reference</label><input id="verse-search" type="search" placeholder="Find a word, thought, or verse… e.g. 2.47" value="${esc(state.query)}" autocomplete="off"></div><div id="search-results" class="search-results" aria-live="polite"></div><div class="verse-body"><div class="verse-heading"><span>अध्याय ${v.chapter} <span>·</span> श्लोक ${v.number}</span><span class="verse-ref">${v.ref}</span></div><p class="chapter-sanskrit" lang="sa">${chapter.name}</p><div class="ornament" aria-hidden="true">✧</div>${verseText(v)}<div class="translation-controls">${languageButtons()}<span class="reader-key-hint"><kbd>←</kbd> <kbd>→</kbd> turn the page</span></div>${v.chapter===13?'<p class="edition-note">Chapter 13 includes Arjuna’s opening question here. Numbering in some 700-verse editions is one lower from 13.2 onward.</p>':''}<div class="verse-source">${sourceLink(sourceUrl(v.ref),'Read the source & commentaries')}</div></div><div class="verse-bottom"><button class="text-button" id="prev-bottom" ${v.ref==='1.1'?'disabled':''}>${icon('left',17)} Previous verse</button><span>${verses.indexOf(v)+1} / 701</span><button class="text-button" id="next-bottom" ${v.ref==='18.78'?'disabled':''}>Next verse ${icon('right',17)}</button></div></article><aside class="reflection-column"><div class="reflection-card"><p class="eyebrow">${icon('sun',17)} INTO EVERYDAY LIFE</p><h2>${refs?refs[0]:chapter.theme}</h2><span class="badge subtle">${refs?'Editorial reflection':'Chapter-level reflection'}</span><p>${refs?refs[1]:chapter.summary}</p><div class="real-life"><span class="small-label">A REAL-LIFE EXAMPLE</span><p>${refs?refs[2]:chapter.example}</p></div><div class="reflect-question"><span class="small-label">PAUSE & ASK YOURSELF</span><p>${refs?refs[3]:chapter.question}</p></div>${!refs?'<p class="fine-print">This is context for the chapter as a whole, not a verse-specific commentary. Compare the translation and the linked source.</p>':''}</div><a class="ask-card" href="#ask"><span class="little-icon">${icon('spark',20)}</span><div><h3>What’s on your mind?</h3><p>Find a reading path for your question.</p></div>${icon('arrow',19)}</a><details class="context-card"><summary>Chapter ${chapter.n} in context</summary><p>${chapter.summary}</p><p class="fine-print">Editorial chapter summary. Read the complete chapter and named commentaries for depth.</p></details></aside></div>`}`;}
function searchResults(){const container=$('#search-results');if(!container)return;let q=state.query.trim().toLocaleLowerCase();if(!q){container.innerHTML='';return;}const found=verses.filter(v=>v.ref===q||v.sanskrit.includes(q)||v.en.toLowerCase().includes(q)||v.hi.includes(q)||v.roman.toLowerCase().includes(q));container.innerHTML=`<p class="fine-print">${found.length} matching verses${found.length>30?' · showing the first 30; narrow your search':''}</p>${found.slice(0,30).map(v=>`<button data-ref="${v.ref}"><b>${v.ref}</b><span>${esc(v.en.slice(0,155))}${v.en.length>155?'…':''}</span>${icon('right',15)}</button>`).join('')}${!found.length?'<p>No match. Try a shorter word in English, Hindi or Sanskrit, or a reference such as 6.26.</p>':''}`;}
function matchJourney(q){
  const normalize=s=>s.normalize('NFKC').toLocaleLowerCase().replace(/[’‘]/g,"'").replace(/[-–—]/g,' ').replace(/\s+/g,' ').trim();
  q=normalize(q);
  const ranked=JOURNEYS.map(j=>({j,score:[...new Set(j.words.map(normalize))].reduce((n,w)=>{
    const literal=w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    const match=/[\u0900-\u097F]/.test(w)?(q.includes(w)?w:''):(q.match(new RegExp('(?:^|[^a-z])'+literal+(w.length>3?'[a-z]*':'')+'(?=$|[^a-z])','i'))?.[0].replace(/^[^a-z]+/,'')||'');
    return n+(match?match.length+(w.includes(' ')?8:0):0);
  },0)})).sort((a,b)=>b.score-a.score);
  return ranked[0]?.score?ranked[0].j:null;
}
function journeyPicker(){return `<div class="topic-picker"><p class="small-label">OR BEGIN WITH A FEELING · ${JOURNEYS.length} READING PATHS</p>${JOURNEY_GROUPS.map(g=>`<div class="journey-topic-group" role="group" aria-labelledby="topics-${g.id}"><h3 id="topics-${g.id}">${g.name} <span lang="hi">${g.hi}</span></h3><div class="chips">${JOURNEYS.filter(x=>(x.group||'everyday')===g.id).map(x=>`<button type="button" class="chip ${x.id===state.journey?'selected':''}" data-journey="${x.id}" aria-pressed="${x.id===state.journey}" title="${esc(x.hi)}">${esc(x.name)}</button>`).join('')}</div></div>`).join('')}</div>`;}
function isCrisis(q){return /kill myself|end my life|suicid|want to die|hurt myself|self.harm|आत्महत्या|मरना चाहता|मरना चाहती/i.test(q);}
function ask(){const j=JOURNEYS.find(x=>x.id===state.journey);return `${header('Bring your question.','मन की बात · A GUIDED READING','Sometimes the first step is finding words for what weighs on you.')}<div class="ask-layout"><section><form class="question-form panel" id="question-form"><label for="question">What are you carrying today?</label><textarea id="question" maxlength="1500" rows="4" placeholder="I work hard, but I’m afraid that I will fail…">${esc(state.question)}</textarea><div class="form-bottom"><small>English or हिन्दी · Your question stays on this page.</small><button class="btn primary" type="submit">Find my reading path ${icon('arrow',18)}</button></div></form>${journeyPicker()}<div id="journey-results" aria-live="polite">${isCrisis(state.question)?`<div class="panel care-message"><h2>You deserve support right now.</h2><p>If you might hurt yourself or are in immediate danger, contact local emergency services or go to the nearest emergency department. Reach out to someone you trust who can stay with you. Scripture can accompany support; it should not be the only support you receive.</p></div>`:''}${state.unknown?'<div class="panel empty"><h3>I couldn’t confidently match that question.</h3><p>Choose the closest feeling above, or rephrase your question. This guide connects themes to prepared readings; it does not invent a scriptural answer to every question.</p></div>':''}${j?journeyView(j):!state.unknown?`<div class="quiet-state"><span lang="sa">अथ संवादः</span><h2>Understanding begins with a question.</h2><p>Choose a concern to see a sequence of verses,<br>with a reason for every step.</p></div>`:''}</div></section><aside class="guide-aside"><p class="eyebrow">HOW THE PATH WORKS</p><h2>More than a verse<br>out of context.</h2><ol><li><b>Recognize</b><p>Begin by understanding the difficulty.</p></li><li><b>Reconsider</b><p>Read a teaching that offers another perspective.</p></li><li><b>Practice</b><p>Leave with one considerate action.</p></li></ol><p class="fine-print">A curated theme guide, not an AI oracle. The reading order and life examples are editorial choices, not a sequence prescribed by the Gita.</p><a class="text-button" href="#sources">Our approach ${icon('arrow',15)}</a></aside></div>`;}
function journeyView(j){return `<div class="journey-intro">
  <p class="eyebrow">YOUR SUGGESTED READING PATH</p><h2>${esc(j.name)}</h2><p class="journey-hindi" lang="hi">${esc(j.hi)}</p><p>${esc(j.intro)}</p>
  <p class="fine-print">If this theme misses your meaning, select a different one above.</p>${languageButtons()}
  ${j.context?`<div class="journey-context"><h3>Keep the context</h3><p>${esc(j.context)}</p>${j.related?.length?`<div class="journey-related"><span>Read alongside:</span>${j.related.map(ref=>`<a href="#reader/${ref}" class="badge">Gita ${ref}</a>`).join('')}</div>`:''}</div>`:''}
  </div><div class="journey-steps">${j.steps.map(([ref,title,why,example],i)=>{const v=byRef[ref];return `<article class="journey-step"><div class="step-number">${String(i+1).padStart(2,'0')}</div><div class="step-main"><div class="step-heading"><h3>${esc(title)}</h3><a href="#reader/${ref}" class="badge">Gita ${ref}</a></div><div class="why"><b>Why ${i===0?'first':i===j.steps.length-1?'last':'next'}:</b> ${esc(why)}</div>${v?verseText(v,true):loading()}<p class="step-reflection"><b>In everyday life:</b> ${esc(example||REFLECTIONS[ref]?.[2]||'Read the complete passage and reflect on the question above.')}</p>${sourceLink(sourceUrl(ref),'Source & context')}</div></article>`;}).join('')}</div>
  ${j.episodes?.length?`<section class="journey-episodes" aria-labelledby="journey-epic-heading"><p class="eyebrow">READ BESIDE THE EPICS</p><h3 id="journey-epic-heading">Different lives, different responses.</h3><p class="fine-print">Episode summaries and modern reflection; these are not additional Gita verses.</p>${j.episodes.map(e=>`<article><h4>${esc(e.title)}</h4><p>${esc(e.text)}</p>${sourceLink(e.url,e.ref)}</article>`).join('')}</section>`:''}
  <div class="practice-prompt"><span>${icon('leaf',24)}</span><div><p class="small-label">ONE THING TO TRY TODAY</p><p>${esc(j.practice)}</p></div></div>`;}
function characters(){const c=CHARACTERS.find(x=>x.id===state.character);return `${header('The lives behind the lessons.','चरित्र और जीवन · LIVES & LESSONS','Read their choices with context. Carry a thoughtful practice into your own life.')}<div class="segmented epic-filter">${['All','Mahabharata','Ramayana'].map(f=>`<button data-epic-filter="${f}" class="${f===state.epicFilter?'selected':''}" aria-pressed="${f===state.epicFilter}">${f}</button>`).join('')}</div><div class="character-layout"><div class="character-list">${CHARACTERS.filter(x=>state.epicFilter==='All'||x.epic===state.epicFilter).map(x=>`<button class="character-button ${x.id===c.id?'selected':''}" data-character="${x.id}" aria-pressed="${x.id===c.id}"><span lang="sa">${x.sa}</span><div><strong>${x.name}</strong><small>${x.trait}</small></div>${icon('right',16)}</button>`).join('')}</div><article class="character-detail panel"><div class="character-header"><div><p class="eyebrow">${c.epic}</p><h2>${c.name}</h2><p>${c.role}</p></div><span lang="sa">${c.sa}</span></div><div class="character-body"><span class="small-label">IN THE TEXT</span><p>${c.story}</p><h3>${c.trait}</h3><p>${c.lesson}</p><div class="real-life"><span class="small-label">TRY THIS · MODERN APPLICATION</span><p>${c.practice}</p></div><details class="nuance"><summary>Keep the nuance</summary><p>${c.nuance}</p></details><div class="source-block"><p class="small-label">READ THE EPISODE</p>${c.gita?c.gita.map(ref=>sourceLink(sourceUrl(ref),`Bhagavad Gita ${ref}`)).join(' '):sourceLink(c.url,c.ref)}</div></div></article></div>`;}
function habitForm(){const h=HABITS.find(x=>x.id===state.habit),draft=state.editing&&state.plan?.habit===state.habit?state.plan:null;return `<form id="habit-form" class="panel habit-form"><p class="eyebrow">01 · CHOOSE A PRACTICE</p><h2>Change one small response.</h2><label for="habit-select">The habit I want to work on</label><select id="habit-select">${HABITS.map(x=>`<option value="${x.id}" ${x.id===h.id?'selected':''}>${x.name}</option>`).join('')}</select><label for="habit-name">My specific habit</label><input id="habit-name" maxlength="100" required value="${esc(draft?.name??(h.id==='custom'?'':h.name))}" placeholder="e.g. Interrupting people when I feel criticized"><label for="habit-cue">When this happens…</label><input id="habit-cue" maxlength="200" required value="${esc(draft?.cue??h.cue)}"><label for="habit-action">I will practice this instead…</label><textarea id="habit-action" maxlength="400" rows="3" required>${esc(draft?.action??h.action)}</textarea><div class="habit-source"><a href="#reader/${h.verse}" class="badge">Gita ${h.verse}</a><p>${h.why}</p></div><button class="btn primary" type="submit">${draft?'Save adjusted practice':'Begin seven practice sessions'} ${icon('arrow',17)}</button>${state.editing&&state.plan?'<button type="button" class="text-button" id="cancel-edit">Cancel changes</button>':''}<p class="fine-print">Saved only in this browser on this device. Seven sessions are a starting structure, not a claim about how quickly a habit changes.</p></form>`;}
function practice(){const p=state.editing?null:state.plan;return `${header('A teaching becomes a practice.','नित्य अभ्यास · DAILY PRACTICE','Choose a small response you can repeat. A missed day is a chance to return.')}<div class="practice-layout">${p?`<section class="panel active-practice"><p class="eyebrow">YOUR PERSONAL PRACTICE</p><h2>${esc(p.name)}</h2><div class="intention"><span class="small-label">WHEN</span><p>${esc(p.cue)}</p><span class="small-label">I WILL</span><p>${esc(p.action)}</p></div><p class="small-label">SEVEN SESSIONS · AT YOUR OWN PACE</p><div class="session-grid">${p.days.map((done,i)=>`<button data-session="${i}" class="session ${done?'done':''}" aria-pressed="${!!done}" aria-label="Session ${i+1}, ${done?'complete':'not complete'}"><span>${done?icon('check',22):String(i+1).padStart(2,'0')}</span><small>Session ${i+1}</small></button>`).join('')}</div><div class="progress-label"><b>${p.days.filter(Boolean).length} of 7 practiced</b><span>${p.days.every(Boolean)?'A good beginning. Keep returning.':'Progress, one return at a time.'}</span></div><progress value="${p.days.filter(Boolean).length}" max="7" aria-label="Practice completion"></progress><div class="habit-source"><a class="badge" href="#reader/${p.verse}">Gita ${p.verse}</a><p>${HABITS.find(h=>h.id===p.habit)?.why||''}</p></div><p class="fine-print">Tap a session after you practice; tap again to undo. This record stays only in this browser.</p><button class="btn secondary" id="edit-practice">Adjust my practice</button><button class="text-button" id="new-practice">Start a new practice</button></section>`:habitForm()}<aside class="practice-aside"><div class="dark-quote"><p class="eyebrow">अभ्यास · ABHYASA</p><span class="large-sa" lang="sa">अभ्यासेन तु कौन्तेय<br>वैराग्येण च गृह्यते</span><p>Practice, with detachment.</p><a href="#reader/6.35">A short paraphrase of Gita 6.35 ${icon('arrow',16)}</a></div><div class="practice-notes"><h3>A gentler kind of discipline.</h3><p><b>Make it specific.</b> Choose a trigger and a response you can recognize.</p><p><b>Keep it possible.</b> A small practice can fit into an ordinary day.</p><p><b>Return without a verdict.</b> A lapse is information. Adjust the plan and continue.</p><p class="fine-print">These are editorial practice suggestions inspired by the cited verses. They do not promise a cure or replace help for a harmful compulsion.</p></div></aside></div>`;}
function formationDiagram(f){if(f.diagram)return drawStudyFormation(f);let dots=[],lines='',labels='';const dot=(x,y,cl='a')=>`<circle cx="${x}" cy="${y}" r="6" class="troop ${cl}"/>`;
if(f.id==='chakra'){[65,110,155].forEach((r,i)=>{lines+=`<circle cx="230" cy="190" r="${r}" fill="none" stroke="currentColor" stroke-dasharray="3 7" opacity=".3"/>`;for(let k=0;k<12+i*5;k++){const a=k/(12+i*5)*Math.PI*2;dots.push(dot(230+Math.cos(a)*r,190+Math.sin(a)*r))}});lines+='<path d="M230 378V225" class="route-path" marker-end="url(#arrowhead)"/>';labels='<text x="230" y="405" text-anchor="middle">Entry · schematic</text><text x="230" y="195" text-anchor="middle">Inner array</text>';}
if(f.id==='garuda'){[[230,60],[205,110],[255,110],[230,150],[230,190],[230,230],[230,270],[230,310],[190,180],[150,200],[110,220],[70,240],[270,180],[310,200],[350,220],[390,240]].forEach(([x,y])=>dots.push(dot(x,y)));lines='<path d="m70 240 120-60 40-120 40 120 120 60M230 150v160" fill="none" stroke="currentColor" opacity=".2"/>';labels='<text x="230" y="35" text-anchor="middle">Bhishma · beak</text><text x="52" y="100">Drona</text><text x="297" y="100">Kritavarman</text><text x="230" y="348" text-anchor="middle">Duryodhana · back</text>';}
if(f.id==='krauncha'){[[230,70],[230,105],[230,140],[230,175],[200,190],[170,210],[140,230],[110,250],[260,190],[290,210],[320,230],[350,250],[210,230],[250,230],[210,270],[250,270],[230,310]].forEach(([x,y])=>dots.push(dot(x,y)));lines='<path d="M230 70v250m-120-70 120-80 120 80" fill="none" stroke="currentColor" opacity=".2"/>';labels='<text x="230" y="40" text-anchor="middle">Krishna &amp; Arjuna · head</text><text x="230" y="355" text-anchor="middle">Pandava positions</text>';}
if(f.id==='sakata'){[[210,70],[250,70],[210,110],[250,110],[130,160],[170,160],[210,160],[250,160],[290,160],[330,160],[130,200],[330,200],[130,240],[330,240],[130,280],[170,280],[210,280],[250,280],[290,280],[330,280],[95,220],[365,220]].forEach(([x,y])=>dots.push(dot(x,y)));lines='<path d="M210 70v90h-80v120h200V160h-80V70" fill="none" stroke="currentColor" opacity=".2"/>';labels='<text x="230" y="40" text-anchor="middle">Front positions</text><text x="230" y="222" text-anchor="middle">Body of array</text><text x="230" y="330" text-anchor="middle">Kaurava positions</text>';}
return `<svg class="formation-svg" viewBox="0 0 460 435" role="img" aria-label="Teaching schematic of ${f.name}; not an exact reconstruction"><defs><marker id="arrowhead" markerWidth="8" markerHeight="8" refX="5" refY="3" orient="auto"><path d="M0 0 6 3 0 6" fill="#b0662f"/></marker></defs>${lines}${dots.join('')}${labels}</svg>`;}
function epic(){const f=FORMATIONS.find(x=>x.id===state.formation);return `${header('Within the great epic.','महाभारत · STORY, DUTY & STRATEGY','Study the roles, difficult choices and formations described in the Mahabharata.')}<div class="segmented epic-tabs">${[['formations','Formations & strategy'],['story','The story & its people']].map(([id,l])=>`<button data-epic-tab="${id}" class="${state.epicTab===id?'selected':''}" aria-pressed="${state.epicTab===id}">${l}</button>`).join('')}</div>${state.epicTab==='formations'?`${formationBrowser(f)}<div class="formation-layout"><div class="formation-board"><div class="board-top"><span class="small-label">VYUHA STUDY · ${f.shape.toUpperCase()}</span><span>व्यूह</span></div>${formationDiagram(f)}<div class="diagram-key"><span><i></i> Illustrative study</span><span>Not to scale</span></div></div><article class="formation-copy"><p class="eyebrow">READING THE FORMATION</p><h2>${f.name}</h2><p>${f.text}</p><ul class="clean-list">${f.points.map(x=>`<li>${x}</li>`).join('')}</ul><div class="real-life"><span class="small-label">BEYOND THE BATTLEFIELD</span><p>${f.lesson}</p></div>${sourceLink(f.url,f.source)}${formationOccurrences(f)}</article></div><div class="source-note">${icon('shield',22)}<p><b>Text first, diagram second.</b> These are modern teaching schematics. The linked passages do not establish these exact shapes, distances, troop counts or movement patterns. This catalogue follows Ganguli’s four war books (Bhishma, Drona, Karna and Shalya), distinguishing named formations, components of compound arrays, and descriptive deployments. Names used in later retellings are not assigned to a passage that does not establish them.</p></div><section class="strategy-section"><h2>A strategy can succeed and still raise moral questions.</h2><div class="two-cards"><article class="panel"><span class="small-label">ROLES & CONSTRAINTS</span><h3>Bhishma and Shikhandin</h3><p>Bhishma tells the Pandavas that he will not strike Shikhandin. The discussion becomes part of their plan against him. The episode shows how vows and relationships constrain a warrior’s actions.</p><p class="fine-print">Modern reflection: understand the constraints of a situation, but examine the ethics of exploiting them.</p>${sourceLink('https://sacred-texts.com/hin/m06/m06108.htm','Bhishma Parva · Ganguli §CVIII')}</article><article class="panel"><span class="small-label">DEPENDENCE ON SUPPORT</span><h3>Abhimanyu’s entry</h3><p>The promise to follow Abhimanyu is central to the proposed plan. The story should not be reduced to “be brave”: it also invites questions about what others owe to someone carrying a dangerous task.</p><p class="fine-print">Modern reflection: do not delegate a difficult responsibility without discussing support and limits.</p>${sourceLink(FORMATIONS[0].url,FORMATIONS[0].source)}</article></div></section>`:epicStory()}`;}
function epicStory(){const roles=[['Krishna','Arjuna’s charioteer and teacher; the speaker of most of the Gita.','Bhagavad Gita 1.21–25; 2.1–11',sourceUrl('1.21')],['Arjuna','Pandava archer, torn by the conflict of fighting his own kin and teachers.','Bhagavad Gita 1.28–47',sourceUrl('1.28')],['Yudhishthira','Pandava king; asks Abhimanyu to enter the circular array and promises support.','Drona Parva §XXXIII',FORMATIONS[0].url],['Bhima','Pandava warrior; promises to follow Abhimanyu into the broken array.','Drona Parva §XXXIII',FORMATIONS[0].url],['Drona','Teacher and commander; arranges and protects the circular array.','Drona Parva §XXXIII',FORMATIONS[0].url],['Bhishma','Kuru elder and commander; leads from the beak of the Garuda formation.','Bhishma Parva §LVI',FORMATIONS[1].url],['Abhimanyu','Arjuna’s son; distinguishes his skill at entry from his inability to exit in danger.','Drona Parva §XXXIII',FORMATIONS[0].url],['Dhrishtadyumna','Panchala prince, among those expected to support Abhimanyu’s entry.','Drona Parva §XXXIII',FORMATIONS[0].url],['Sanjaya','Narrates the battlefield dialogue to Dhritarashtra in the Gita’s frame.','Bhagavad Gita 1.1–2',sourceUrl('1.1')]];return `<div class="story-intro panel"><p class="eyebrow">AN ORIENTATION</p><h2>A family conflict. A crisis of dharma.</h2><p>The Mahabharata tells of the Kuru family, especially the Pandavas and Kauravas. Its world includes inheritance disputes, the dice game, exile, failed attempts at peace, the Kurukshetra war and the struggle to live with its aftermath. It is far larger than a book of battlefield tactics.</p><p>The Gita sits inside the Bhishma Parva. Krishna and Arjuna’s dialogue is framed by Sanjaya’s narration to Dhritarashtra.</p>${sourceLink('https://sacred-texts.com/hin/maha/index.htm','Read Ganguli’s Mahabharata by book')}</div><div class="story-stages">${[['Sabha Parva','The dice hall','The episode exposes the failure of judgment and the moral responsibility of an assembly.','https://sacred-texts.com/hin/m02/m02066.htm'],['Bhishma Parva','The question before action','Arjuna’s crisis opens into the Gita; the war raises questions of duty, loyalty and cost.',sourceUrl('2.7')],['Drona Parva','The burden of a plan','Abhimanyu’s entry brings knowledge, responsibility and dependence on others into focus.',FORMATIONS[0].url],['Shanti Parva','After victory','Yudhishthira’s grief complicates any simple equation of victory with peace.','https://sacred-texts.com/hin/m12/m12a027.htm']].map(([a,b,c,u],i)=>`<article><span class="stage-number">0${i+1}</span><p class="eyebrow">${a}</p><h3>${b}</h3><p>${c}</p>${sourceLink(u,'Read the passage')}</article>`).join('')}</div><h2 class="section-title">Know who is doing what.</h2><div class="role-grid">${roles.map(([n,r,l,u])=>`<article class="panel"><h3>${n}</h3><p>${r}</p>${sourceLink(u,l)}</article>`).join('')}</div><p class="fine-print">This is an introductory selection of episodes and roles, not an exhaustive retelling. Dates, supernatural events and military details in the sacred narrative are not presented here as independently established history.</p>`;}
function scriptures(){return `${header('A library, not a single book.','शास्त्र परिचय · SCRIPTURE LIBRARY','An introduction to the families of Hindu texts, and how to approach them.')}<div class="scripture-note"><span lang="sa">श्रुति <i>·</i> स्मृति</span><p><b>Shruti</b> commonly refers to the Vedic revelation; <b>smriti</b> to remembered tradition. Texts, commentaries and devotional communities give these categories different emphases.</p></div><div class="scripture-grid">${SCRIPTURES.map((s,i)=>`<article class="scripture-card"><span class="scripture-number">0${i+1}</span><p class="scripture-sa" lang="sa">${s.sa}</p><p class="eyebrow">${s.tag}</p><h2>${s.title}</h2><p>${s.text}</p><details><summary>A way to begin</summary><p>${s.question}</p></details>${s.title==='The Bhagavad Gita'?'<a class="text-button" href="#reader">Open the Gita '+icon('arrow',16)+'</a>':sourceLink(SOURCES[s.source].url,'Explore the source')}</article>`).join('')}</div><div class="source-note">${icon('book',22)}<p><b>Three layers to keep distinct:</b> the original passage, a named translator or commentator’s interpretation, and a modern application. They belong in conversation, but they are not interchangeable.</p></div>`;}
function sources(){return `${header('Know where a teaching comes from.','प्रमाण · SOURCES & APPROACH','References are part of the reading experience, not an afterthought.')}<div class="source-policy"><div><p class="eyebrow">OUR EDITORIAL APPROACH</p><h2>Faithful to the text.<br>Honest about interpretation.</h2></div><div><p>Sanskrit verses and attributed translations are kept separate from our summaries, guided reading orders and modern examples. Those applications are editorial interpretations, not quotations or instructions claimed to appear in scripture.</p><p>Hindu traditions contain meaningful differences. A source establishes what a text or commentator says; it does not prove every historical, metaphysical or supernatural claim.</p></div></div><div class="sources-list">${SOURCES.map((s,i)=>`<article><span class="source-number">0${i+1}</span><div><p class="eyebrow">${s.type}</p><h3>${s.title}</h3><p>${s.detail}</p>${sourceLink(s.url,'Visit the source')}</div></article>`).join('')}</div><div class="two-cards"><section class="panel"><h3>Why does the reader show 701?</h3><p>The commonly cited count is 700. This corpus includes Arjuna’s opening question at 13.1, followed by Krishna’s answer at 13.2. In editions that omit the question, chapter 13’s later numbering is one lower. Both conventions must be checked when comparing references.</p><a class="text-button" href="#reader/13.1">See the opening question ${icon('arrow',16)}</a></section><section class="panel"><h3>What has been checked?</h3><p>All 18 chapters have sequential, unique verse references and nonempty Sanskrit, Hindi and English text. Key guided verses were compared with IIT Kanpur’s Gita Supersite. Structural checks are not a complete scholarly proofreading of every character.</p><p>Digitization can contain errors. Use the linked source and named commentaries when precision matters. No claim of infallibility is made.</p></section><section class="panel"><h3>Translations and corpus provenance</h3><p>English is attributed to Swami Sivananda. Hindi is attributed to Swami Ramsukhdas, except 13.1, which uses Swami Tejomayananda because the Ramsukhdas field has no translation. The original archived dataset is used rather than its AI-corrected counterpart.</p>${sourceLink('https://github.com/gita/gita/blob/main/archive/translation_old.json','Original translation archive')}<br>${sourceLink('/dataset-license.txt','Repository license')}</section><section class="panel"><h3>Artwork and battle diagrams</h3><p>The chariot painting is contemporary AI-generated artwork inspired by Indian miniature painting. The animated Sudarshan Chakra and the mythological header and footer ornaments use contemporary AI-generated decorative artwork. It is not a medieval artifact. Formation diagrams are modern schematics; they are not archaeological plans or validated battle simulations.</p><p class="fine-print">Site content assembled September 2026. Practice records remain in your browser. Questions are matched locally to curated themes and are not sent to an AI service.</p></section></div>`;}
function render(){const views={reader,ask,mantras,characters,practice,epic,scriptures,sources};$('#app').innerHTML=shell(views[state.page]());document.title=`${NAV.find(n=>n[0]===state.page)?.[2]||'Sources'} · Dharma`;bind();bindMantras();if(state.page==='reader')searchResults();}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000);}
function savePlan(p){if(!storage.set('dharma-practice',p)){state.plan=p;render();toast('Practice is available this session, but this browser could not save it.');return;}state.plan=p;render();}
function nextVerse(delta){const i=verses.findIndex(v=>v.ref===state.ref),v=verses[i+delta];if(v){state.query='';go('reader',v.ref);}}
function chooseJourney(id){state.journey=id;state.unknown=false;render();$('#journey-results')?.scrollIntoView({behavior:'smooth',block:'start'});}
function bind(){const on=(q,event,fn)=>$(q)?.addEventListener(event,fn);on('#menu-toggle','click',()=>{const open=$('#side').classList.toggle('is-open');$('#menu-toggle').setAttribute('aria-expanded',open);$('#menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');});on('#retry-load','click',loadVerses);on('#chapters-toggle','click',()=>{const c=$('#chapter-index');c.hidden=!c.hidden;$('#chapters-toggle').setAttribute('aria-expanded',!c.hidden);});on('#chapter-select','change',e=>{state.query='';go('reader',`${e.target.value}.1`)});on('#verse-select','change',e=>{state.query='';go('reader',e.target.value)});on('#verse-search','input',e=>{state.query=e.target.value;searchResults()});on('#prev-top','click',()=>nextVerse(-1));on('#prev-bottom','click',()=>nextVerse(-1));on('#next-top','click',()=>nextVerse(1));on('#next-bottom','click',()=>nextVerse(1));
on('#question','input',e=>{state.question=e.target.value});on('#question-form','submit',e=>{e.preventDefault();if(!state.question.trim()){toast('Write a question or choose a feeling below.');$('#question').focus();return;}const j=matchJourney(state.question);state.journey=j?.id||null;state.unknown=!j;render();$('#journey-results').scrollIntoView({behavior:'smooth',block:'start'});});
on('#habit-select','change',e=>{state.habit=e.target.value;state.editing=true;const h=HABITS.find(x=>x.id===state.habit);render();$('#habit-name').value=h.id==='custom'?'':h.name;$('#habit-cue').value=h.cue;$('#habit-action').value=h.action;});on('#habit-form','submit',e=>{e.preventDefault();const h=HABITS.find(x=>x.id===state.habit),name=$('#habit-name').value.trim(),cue=$('#habit-cue').value.trim(),action=$('#habit-action').value.trim();if(!name||!cue||!action){toast('Please write a specific habit, trigger and replacement action.');return;}const days=state.editing&&state.plan&&state.plan.habit===h.id?[...state.plan.days]:Array(7).fill(false);state.editing=false;savePlan({habit:h.id,name,cue,action,verse:h.verse,days});toast('Your practice is ready.');});
on('#new-practice','click',()=>{if(confirm('Replace the current practice and its seven-session record?')){state.plan=null;state.editing=false;storage.set('dharma-practice',null);render();}});on('#cancel-edit','click',()=>{state.editing=false;render()});on('#edit-practice','click',()=>{state.habit=state.plan.habit;state.editing=true;render();});}

$('#app').addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.chapter){state.query='';go('reader',`${d.chapter}.1`)}if(d.ref){state.query='';go('reader',d.ref)}if(d.lang){state.lang=d.lang;storage.set('dharma-lang',d.lang);const y=window.scrollY;render();window.scrollTo(0,y)}if(d.journey)chooseJourney(d.journey);if(d.character){state.character=d.character;render()}if(d.epicFilter){state.epicFilter=d.epicFilter;const c=CHARACTERS.find(x=>x.id===state.character);if(d.epicFilter!=='All'&&c.epic!==d.epicFilter)state.character=CHARACTERS.find(x=>x.epic===d.epicFilter).id;render()}if(d.formationSide){formationSide=d.formationSide;if(!visibleFormations().some(f=>f.id===state.formation))state.formation=visibleFormations()[0].id;const y=window.scrollY;render();window.scrollTo(0,y)}if(d.formation){const y=window.scrollY,menu=$('.formation-tabs')?.scrollTop||0;state.formation=d.formation;render();if($('.formation-tabs'))$('.formation-tabs').scrollTop=menu;window.scrollTo(0,y)}if(d.epicTab){state.epicTab=d.epicTab;render()}if(d.session!==undefined&&state.plan){const days=[...state.plan.days],n=Number(d.session);if(n>=0&&n<7){days[n]=!days[n];const y=window.scrollY;savePlan({...state.plan,days});window.scrollTo(0,y);toast(days[n]?'Practice recorded. Keep returning.':'Session marked as not complete.');}}});
window.addEventListener('hashchange',parseRoute);
window.addEventListener('keydown',e=>{handleReadingArrows(e);if(e.key==='Escape'&&$('#side')?.classList.contains('is-open')){$('#side').classList.remove('is-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').focus()}});
async function loadVerses(){loadError=false;try{const r=await fetch('/gita.json');if(!r.ok)throw Error('Unable to open text');const data=await r.json();if(!Array.isArray(data)||data.length!==701)throw Error('Incomplete text');verses=data;byRef=Object.fromEntries(data.map(v=>[v.ref,v]));parseRoute()}catch(err){loadError=true;render();}}
function registerTools(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const lifecycle=new AbortController();const defs=[{name:'open_gita_verse',description:'Open a chapter-and-verse reference in the visible Gita reader.',inputSchema:{type:'object',properties:{reference:{type:'string'}},required:['reference'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.reference!=='string'||!byRef[input.reference])throw Error('Supply an existing reference such as 2.47.');state.query='';history.replaceState(null,'',`#reader/${input.reference}`);state.page='reader';state.ref=input.reference;render();return {reference:state.ref,sanskrit:byRef[state.ref].sanskrit,source:sourceUrl(state.ref)}}},{name:'show_gita_reading_path',description:'Match a concern to a curated theme and show its ordered reading path. Does not create new scripture or store the question.',inputSchema:{type:'object',properties:{question:{type:'string',maxLength:1500}},required:['question'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.question!=='string'||!input.question.trim()||input.question.length>1500)throw Error('Supply a question between 1 and 1500 characters.');const j=matchJourney(input.question);state.question=input.question;state.journey=j?.id||null;state.unknown=!j;state.page='ask';history.replaceState(null,'','#ask');render();return {theme:j?.name||null,verses:j?.steps.map(s=>s[0])||[],matched:!!j,method:'Curated theme matching'}}}];for(const t of defs){try{Promise.resolve(ctx.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
parseRoute();loadVerses();registerTools();
